package com.bank.multidb.audit.model;

import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "audit_records")
public class AuditRecord {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    @Column(name = "account_id", nullable = false) private String accountId;
    @Column(nullable = false) private String action;
    @Column(nullable = false, length = 500) private String detail;
    @Column(name = "at_time") private LocalDateTime atTime;

    protected AuditRecord() {}
    public AuditRecord(String accountId, String action, String detail) {
        this.accountId = accountId; this.action = action; this.detail = detail;
        this.atTime = LocalDateTime.now();
    }
    public Long getId() { return id; }
    public String getAccountId() { return accountId; }
    public String getAction() { return action; }
}
