// ─── File: src/main/java/com/bank/multidb/service/BankingService.java ───
package com.bank.multidb.service;

import com.bank.multidb.audit.model.AuditRecord;
import com.bank.multidb.audit.repository.AuditRecordRepository;
import com.bank.multidb.core.model.Account;
import com.bank.multidb.core.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class BankingService {

    private final AccountRepository accountRepo;        // CORE db
    private final AuditRecordRepository auditRepo;      // AUDIT db

    // CORE transaction manager — commits against coredb ONLY
    @Transactional("coreTransactionManager")
    public void debit(String accountId, BigDecimal amount) {
        Account account = accountRepo.findById(accountId).orElseThrow();
        account.setBalance(account.getBalance().subtract(amount));
        accountRepo.save(account);
        log.info("[coreTransactionManager] debited Rs.{} from {} (coredb)", amount, accountId);
    }

    // AUDIT transaction manager — commits against auditdb ONLY (separate transaction)
    @Transactional("auditTransactionManager")
    public void audit(String accountId, String action, String detail) {
        auditRepo.save(new AuditRecord(accountId, action, detail));
        log.info("[auditTransactionManager] wrote audit for {} (auditdb)", accountId);
    }

    // Orchestration: TWO separate local transactions (NOT atomic across DBs without XA)
    public void debitWithAudit(String accountId, BigDecimal amount) {
        debit(accountId, amount);                 // commits in coredb
        audit(accountId, "DEBIT", "amount=" + amount); // commits in auditdb (retry-safe if it fails)
        log.info("Completed debit+audit — two independent transactions (consider XA/saga for atomicity)");
    }
}
