package com.bank.multidb.controller;

import com.bank.multidb.service.BankingService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/banking")
@RequiredArgsConstructor
public class BankingController {

    private final BankingService service;

    @PostMapping("/{accountId}/debit")
    public Map<String, Object> debit(@PathVariable String accountId, @RequestParam BigDecimal amount) {
        service.debitWithAudit(accountId, amount);
        return Map.of("accountId", accountId, "debited", amount, "note", "core+audit in separate transactions");
    }
}
