package com.bank.multidb.config;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class MultiDbBeanTest {

    @Test
    void coreAndAuditUseSeparateBeanNames() {
        // Each DB has its own trio of beans, referenced by name in @EnableJpaRepositories.
        String[] coreBeans = {"coreDataSource", "coreEntityManagerFactory", "coreTransactionManager"};
        String[] auditBeans = {"auditDataSource", "auditEntityManagerFactory", "auditTransactionManager"};
        assertThat(coreBeans).doesNotContainAnyElementsOf(java.util.List.of(auditBeans));
    }

    @Test
    void entityPackagesAreSeparate() {
        // Core factory scans core.model; audit factory scans audit.model — no mixing.
        assertThat("com.bank.multidb.core.model").isNotEqualTo("com.bank.multidb.audit.model");
    }

    @Test
    void transactionalSpansOneDatabase() {
        // @Transactional("coreTransactionManager") commits coredb ONLY.
        // Cross-DB atomicity needs XA/JTA or a saga — a plain @Transactional does NOT provide it.
        assertThat("one-db-per-transaction").isNotEqualTo("two-phase-commit");
    }
}
```
